# Finite differences
d1 = t2 - t1
d2 = t3 - 2*t2 + t1
d3 = t4 - 3*t3 + 3*t2 - t1

# Enforce cubic difficulty: third difference must be nonzero.
if d3 == 0:
    return (False, None)

# Newton forward formula for degree <= 3 sequences:
