    # Not needed for this task; protect against misuse.
    raise ValueError('comb r out of range')

answer = t1 + comb(n,1)*d1 + comb(n,2)*d2 + comb(n,3)*d3

# As a mild sanity check, the sequence should be increasing so answer >= t4 for k >= 5
